class OrganizationalUnit {}

class Division extends OrganizationalUnit {
  + manager
}

class Subdivision extends OrganizationalUnit {}

class Branch extends Subdivision {
  + address
  + branchNumber
}

class AccountType {
  + interestRate
  + monthlyFee
  + privileges
}

class Account {
  + accountNumber
  + balance
  + creditOrOverdraftLimit
}

class MortgageAccount extends Account {
  + collateralProperty
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate
}

class JointAccount extends Account {}

class Customer {
}

class Employee {
}

OrganizationalUnit "1" -- "*" Subdivision : subdivision
Division "1" -- "*" Employee : has
Employee "1" -- "*" Customer : personal banker
Branch "1" -- "*" Account : opens
AccountType "*" -- "1" Account : has
Account "1" -- "*" Account : secondary cards

@enduml

